# Let's analyze the grid structure more carefully
# Check for regular patterns in rows and columns

# Check if columns are all same value
col_counts = {}
for j in range(24):
    col = grid[:, j]
    count = tuple(sorted([(v, int(np.sum(col == v))) for v in [2, 5]]))
    col_counts[j] = count

print("Column uniformity (value, count):")
for j, count in col_counts.items():
    if count in [(3, 0), (0, 3)]:
        print(f"  Col {j}: {count[0]} ({count[1]} only)")
    else:
        print(f"  Col {j}: {count}")

# Check row uniformity
print("\nRow uniformity (value, count):")
for i in range(28):
    row = grid[i, :]
    count = tuple(sorted([(v, int(np.sum(row == v))) for v in [2, 5]]))
    if count in [(3, 0), (0, 3)]:
        print(f"  Row {i}: {count[0]} ({count[1]} only)")

# Check if there are pattern blocks
# Maybe 6x6 or 4x4 blocks?
print("\n" + "="*50)
print("Looking for 2x2 blocks")
print("="*50)
block_counts = {}
for i in range(27):
    for j in range(23):
        block = grid[i:i+2, j:j+2]
        block_key = tuple(block.flatten())
        block_counts[block_key] = block_counts.get(block_key, 0) + 1

print(f"Number of unique 2x2 blocks: {len(block_counts)}")
print(f"Most common 2x2 blocks:")
for key, count in sorted(block_counts.items(), reverse=True)[:10]:
    print(f"  {key}: {count}")

# Let's analyze the positions of 2s more carefully
# They seem sparse - maybe they form a meaningful pattern

# Get all positions where value is 2
pos_2 = np.argwhere(grid == 2)
print(f"Number of 2 positions: {len(pos_2)}")
print(f"Positions (first 20):")
for i, p in enumerate(pos_2[:20]):
    print(f"  ({p[0]}, {p[1]})")

# Let's check the deltas between consecutive 2 positions
# Sort by row then column
sorted_pos = pos_2[np.lexsort((pos_2[:, 0], pos_2[:, 1]))]

# Check if there's a regular structure
# Look at the column indices for 2s in each row
cols_with_2 = {}
for row, col in pos_2:
    if row not in cols_with_2:
        cols_with_2[row] = []
    cols_with_2[row].append(col)

print("\nColumns with 2s by row (first 10 rows):")
for row in range(10):
    if row in cols_with_2:
        print(f"  Row {row}: {cols_with_2[row]}")
    else:
        print(f"  Row {row}: -")

# Check the distribution of 2s per row
print("\n2s per row:")
for row in range(28):
    count = np.sum(grid[row] == 2)
    if count > 0:
        print(f"  Row {row}: {count}")

